import {Experience,NPCS} from './experience.js';
import {BODIES,BY_ID,RADIUS,NEXT,DEFAULT_EXPERIMENT,SIZES,METHODS,LEVELS,WALK_SPEED,RUN_SPEED,placements,connections,reachable,portStates,regionAt,insideBody,boundaryWalls,portSegment,segmentDistance,LANDING,POINTS} from './architecture.js';
import {planTransfer,validatePlan,positionDuring} from './transport.js';
export const CABIN={x:-6.55,z:2.05,w:3.9,d:3.9};
export function fixedWalls(){return[{a:[LANDING.x,2.06],b:[-.4,2.06]},{a:[LANDING.x,5.94],b:[-.4,5.94]},{a:[-2.34,2],b:[-2.34,2.4]},{a:[-2.34,5.6],b:[-2.34,6]},{a:[-.46,2],b:[-.46,3]},{a:[-.46,5],b:[-.46,6]}];}
export class Simulation{
 constructor(e=DEFAULT_EXPERIMENT){this.reset(e);}
 reset(e=this.experiment??DEFAULT_EXPERIMENT){this.experiment={...DEFAULT_EXPERIMENT,...e};if(!SIZES[this.experiment.size]||!METHODS[this.experiment.method])throw Error('Unknown experiment');this.phase='A';this.positions=placements('A',this.experiment);this.player={x:-1.2,y:LEVELS[1],z:4,yaw:Math.PI/2,pitch:0,owner:'F1'};this.doors=Object.fromEntries(BODIES.flatMap(b=>b.doors.map(d=>[d.id,d.open])));this.mode='idle';this.elapsed=0;this.plan=null;this.stageIndex=-1;this.paused=false;this.speed=2;this.experimental=false;this.shutter=0;this.passenger=null;this.evacuationActive=false;this.liftY=LEVELS[1];this.liftTarget=this.liftY;this.liftFrom=this.liftY;this.liftTime=0;this.liftActive=false;this.liftPassenger=false;this.message='第三層の住戸から、南北に分岐する通路を探索できます。';this.history=[];this.lastCheck=null;this.completed=0;this.clock=0;this.experience=new Experience(this);this.invalidate();}
 get levels(){return LEVELS;}
 get next(){return NEXT[this.phase];}
 invalidate(){this._colliders=null;this._links=null;this._ports=null;this._joints=null;this._reach=null;this._targetReach=null;}
 get liveConnections(){return this._links??=connections(this.phase,this.experiment,this.doors).map(c=>this.shutter>.01?{...c,status:'blocked'}:c);}
 get livePorts(){return this._ports??=portStates(this.phase,this.experiment,this.doors).map(p=>this.shutter>.01?{...p,status:'blocked',openings:[],masked:[{a:p.a,b:p.b}]}:p);}
 get joints(){return this._joints??=this.liveConnections.filter(c=>c.status!=='blocked').map(c=>({...c.bridge,id:c.id,height:c.height,status:c.status,a:c.a,b:c.b}));}
 get bridges(){return this.joints;}
 get liveReachable(){if(this._reach)return this._reach;const seen=new Set(['F0','F1']);let changed=true;while(changed){changed=false;for(const c of this.liveConnections.filter(c=>c.status==='pass')){if(seen.has(c.a)&&!seen.has(c.b)){seen.add(c.b);changed=true;}if(seen.has(c.b)&&!seen.has(c.a)){seen.add(c.a);changed=true;}}}return this._reach=seen;}
 get targetReachable(){return this._targetReach??=reachable(this.next,this.experiment,this.doors);}
 get targetRiskRegions(){return new Set([...this.liveReachable].filter(n=>n.includes('/')&&!this.targetReachable.has(n)));}
 get targetIsolated(){return[...new Set([...this.targetRiskRegions].map(n=>n.split('/')[0]))];}
 portIsOpen(id,p){const q=this.livePorts.find(q=>q.key===`${id}:${p.id}`);return!!q&&q.status!=='blocked';}
 get owner(){return this.ownerAt(this.player.x,this.player.z,this.player.y);}
 get ownerRegion(){return this.regionAtPoint(this.player.x,this.player.z,this.player.y);}
 ownerAt(x,z,y=this.player.y){if(x>=CABIN.x&&x<=CABIN.x+CABIN.w&&z>=CABIN.z&&z<=CABIN.z+CABIN.d&&Math.abs(y-this.liftY)<.01)return'lift';for(const b of BODIES){const p=this.positions[b.id];if(Math.abs(p.y-y)<.01&&insideBody(b,x-p.x,z-p.z))return b.id;}const l=LEVELS.findIndex(q=>Math.abs(q-y)<.01);if(l>=0&&x>=LANDING.x&&x<=-.4&&z>=2&&z<=6)return`F${l}`;if(l>=0&&x>=-2.65&&x<=-2.4&&z>=2.4&&z<=5.6)return`F${l}`;for(const q of this.joints)if(Math.abs(q.y-y)<.01&&x>=q.x&&x<=q.x+q.w&&z>=q.z&&z<=q.z+q.d)return`joint:${q.id}`;return null;}
 regionAtPoint(x,z,y=this.player.y){const id=this.ownerAt(x,z,y);if(BY_ID[id])return regionAt(id,x-this.positions[id].x,z-this.positions[id].z,this.doors);return id;}
 floorSupports(x,z,y){return!!this.ownerAt(x,z,y);}
 colliders(){if(this._colliders)return this._colliders;const lines=[],solids=[],add=(l,owner,y,p={x:0,z:0})=>lines.push({a:[l.a[0]+p.x,l.a[1]+p.z],b:[l.b[0]+p.x,l.b[1]+p.z],owner,y});
  for(let i=0;i<2;i++){const y=LEVELS[i];for(const l of fixedWalls())add(l,`F${i}`,y);if(this.liftActive||Math.abs(this.liftY-y)>.01)add({a:[-2.5,2.4],b:[-2.5,5.6]},`F${i}`,y);const p=this.livePorts.find(p=>p.key===`F${i}:E`);for(const m of p?.masked??[{a:1,b:3}])add({a:[-.46,LANDING.z+m.a],b:[-.46,LANDING.z+m.b]},`F${i}`,y);}
  for(const l of[{a:[CABIN.x+.06,CABIN.z],b:[CABIN.x+.06,CABIN.z+CABIN.d]},{a:[CABIN.x,CABIN.z+.06],b:[CABIN.x+CABIN.w,CABIN.z+.06]},{a:[CABIN.x,CABIN.z+CABIN.d-.06],b:[CABIN.x+CABIN.w,CABIN.z+CABIN.d-.06]},{a:[-2.71,2.05],b:[-2.71,2.4]},{a:[-2.71,5.6],b:[-2.71,5.95]}])add(l,'lift',this.liftY);if(this.liftActive)add({a:[-2.71,2.4],b:[-2.71,5.6]},'lift',this.liftY);
  for(const b of BODIES){const q=this.positions[b.id];for(const l of[...boundaryWalls(b),...b.walls,...b.doors.filter(d=>!this.doors[d.id])])add(l,b.id,q.y,q);for(const p of b.ports){const state=this.livePorts.find(s=>s.key===`${b.id}:${p.id}`);for(const m of state?.masked??[{a:p.a,b:p.b}])add(portSegment(b,{...p,...m}),b.id,q.y,q);for(const o of state?.openings??[])if(o.height<2)add(portSegment(b,{...p,a:o.a,b:o.b}),b.id,q.y,q);}for(const n of NPCS.filter(n=>n.body===b.id))solids.push({x:q.x+n.x-n.radius,z:q.z+n.z-n.radius,w:n.radius*2,d:n.radius*2,y:q.y,owner:b.id});for(const s of[...b.solids,...b.furniture])solids.push({...s,x:s.x+q.x,z:s.z+q.z,y:q.y,owner:b.id});}
  for(const source of this.joints){const j=source.orientation==='EW'?{...source,x:source.x-.26,w:source.w+.52}:{...source,z:source.z-.26,d:source.d+.52};const sides=j.orientation==='EW'?[{a:[j.x,j.z-.06],b:[j.x+j.w,j.z-.06]},{a:[j.x,j.z+j.d+.06],b:[j.x+j.w,j.z+j.d+.06]}]:[{a:[j.x-.06,j.z],b:[j.x-.06,j.z+j.d]},{a:[j.x+j.w+.06,j.z],b:[j.x+j.w+.06,j.z+j.d]}];for(const l of sides)add(l,'joint',j.y);}return this._colliders={lines,solids};
 }
 isFree(x,z,y=this.player.y,radius=RADIUS){if(!this.floorSupports(x,z,y))return false;for(let i=0;i<16;i++){const a=i*Math.PI/8;if(!this.floorSupports(x+Math.cos(a)*radius,z+Math.sin(a)*radius,y))return false;}const c=this.colliders();for(const l of c.lines)if(Math.abs(l.y-y)<.01&&segmentDistance(x,z,l.a,l.b)<radius+.06-1e-7)return false;for(const s of c.solids)if(Math.abs(s.y-y)<.01&&Math.hypot(Math.max(s.x-x,0,x-s.x-s.w),Math.max(s.z-z,0,z-s.z-s.d))<radius+.01)return false;return true;}
 move(dx,dz){if(this.experience.visit)return false;if(!['idle','warning','evacuate'].includes(this.mode)||this.liftActive)return false;let moved=false;const steps=Math.max(1,Math.ceil(Math.hypot(dx,dz)/.08));for(let i=0;i<steps;i++)for(const[ax,az]of[[dx/steps,0],[0,dz/steps]]){const x=this.player.x+ax,z=this.player.z+az,owner=this.ownerAt(x,z),region=this.regionAtPoint(x,z);if(['warning','evacuate'].includes(this.mode)&&!this.experimental&&BY_ID[owner]&&!this.targetReachable.has(region)&&this.ownerRegion!==region&&!this.evacuationActive){this.message='閉鎖予定の内部通路への新規入場を制限中です。';continue;}if(this.isFree(x,z)){this.player.x=x;this.player.z=z;moved=true;if(this.targetReachable.has(region))this.evacuationActive=false;}}this.player.owner=this.owner;return moved;}
 walk(forward,side,dt,run=false){if(this.experience.blocking){if(forward<0)this.experience.leave();return false;}const n=Math.hypot(forward,side)||1,d=dt*(run?RUN_SPEED:WALK_SPEED),yaw=this.player.yaw;return this.move((Math.sin(yaw)*forward-Math.cos(yaw)*side)/n*d,(Math.cos(yaw)*forward+Math.sin(yaw)*side)/n*d);}
 startTransfer(){if(this.mode!=='idle'||this.liftActive||this.experience.blocking)return false;this.plan=planTransfer(this.phase,this.next,this.experiment);this.lastCheck=validatePlan(this.plan);if(!this.lastCheck.ok){this.message=`搬送不成立：${this.plan.planningError??this.lastCheck.errors[0]?.type}`;return false;}this.mode='warning';this.elapsed=0;this.paused=false;this.evacuationActive=!this.targetReachable.has(this.ownerRegion)||this.owner?.startsWith('joint:');this.message=`5秒後に搬送。閉鎖予定の通路：${this.targetIsolated.join('・')||'なし'}。継手から離れてください。`;return true;}
 cancelWarning(){if(['warning','evacuate'].includes(this.mode)){this.mode='idle';this.plan=null;this.elapsed=0;this.message='搬送準備を取り消しました。';}}
 beginClosing(){const own=this.owner;if(!this.experimental&&BY_ID[own]&&!this.targetReachable.has(this.ownerRegion)){this.mode='evacuate';this.message='退避待ち：この内部通路は次周期で到達不能になります。安全な通路へ歩いて退避してください。';return;}let seam=!own||own.startsWith('joint:');for(let i=0;i<16&&!seam;i++){const a=i*Math.PI/8;if(this.ownerAt(this.player.x+Math.cos(a)*.46,this.player.z+Math.sin(a)*.46)!==own)seam=true;}if(seam){this.mode='evacuate';this.message='格納する接合トンネルをまたいでいます。区画の内側へ移動してください。';return;}this.passenger=BY_ID[own]?{id:own,x:this.player.x-this.positions[own].x,z:this.player.z-this.positions[own].z}:null;this.mode='closing';this.elapsed=0;this.invalidate();}
 tick(dt){this.clock+=dt;if(this.paused)return;this.experience.tick(dt);const delta=Math.min(.1,dt)*this.speed;if(this.liftActive){this.liftTime+=delta;const t=Math.min(1,this.liftTime/5);this.liftY=this.liftFrom+(this.liftTarget-this.liftFrom)*t;if(this.liftPassenger)this.player.y=this.liftY;this.invalidate();if(t===1){this.liftActive=false;this.message='固定EVが着床しました。乗場扉を開放します。';}}if(this.mode==='idle')return;if(this.mode==='evacuate'){this.beginClosing();return;}this.elapsed+=delta;if(this.mode==='warning'){if(this.elapsed>=5)this.beginClosing();return;}if(this.mode==='closing'){this.shutter=Math.min(1,this.elapsed/1.2);this.invalidate();if(this.elapsed>=1.5){this.mode='moving';this.elapsed=0;this.shutter=1;}return;}
  if(this.mode==='moving'){this.positions=positionDuring(this.plan,Math.min(this.elapsed,this.plan.duration));let sum=0;this.stageIndex=this.plan.stages.findIndex(s=>{sum+=s.duration;return this.elapsed<sum;});if(this.passenger){const p=this.positions[this.passenger.id];this.player.x=p.x+this.passenger.x;this.player.z=p.z+this.passenger.z;this.player.y=p.y;}this.invalidate();if(this.elapsed>=this.plan.duration){this.phase=this.plan.to;this.mode='opening';this.elapsed=0;this.completed++;this.experience.event('dock',this.owner);this.history.unshift(`${this.plan.from}→${this.phase}：${this.lastCheck.checks}連続検査・離隔違反0`);this.history=this.history.slice(0,6);}return;}
  if(this.mode==='opening'){this.shutter=1-Math.min(1,this.elapsed/1.2);this.invalidate();if(this.elapsed>=1.3){this.mode='idle';this.shutter=0;this.invalidate();this.message=BY_ID[this.owner]&&!this.liveReachable.has(this.ownerRegion)?this.owner==='C0'?'予備廊下の保管状態です。Bで再挿入されます。':'意図的な孤立状態です。次のAで再接続できます。':'搬送完了。近道・環状路・開口ごとの変化を探索できます。';}}
 }
 useLift(){if(this.mode!=='idle'||this.liftActive)return false;const own=this.owner;if(own==='lift'){if(this.player.x>-3.15){this.message='かごの奥へ進んでください。';return false;}this.liftPassenger=true;this.liftTarget=this.liftY===0?LEVELS[1]:0;}else if(own==='F0'||own==='F1'){if(Math.abs(this.liftY-this.player.y)<.01){this.message='西側のかごへ歩いて入り、Eで昇降します。';return false;}this.liftPassenger=false;this.liftTarget=this.player.y;}else{this.message='固定EVの乗場か、かご内で操作してください。';return false;}this.liftFrom=this.liftY;this.liftTime=0;this.liftActive=true;this.invalidate();this.message='かご扉・乗場扉を閉鎖して昇降中。';return true;}
 interact(){if(this.experience.interact())return;if(!['idle','warning','evacuate'].includes(this.mode))return;if(['lift','F0','F1'].includes(this.owner)){this.useLift();return;}let near=null,dist=1.7;for(const b of BODIES){const p=this.positions[b.id];if(Math.abs(p.y-this.player.y)>.01)continue;for(const d of b.doors){const n=segmentDistance(this.player.x-p.x,this.player.z-p.z,d.a,d.b);if(n<dist){near=d;dist=n;}}}if(!near){this.message='E：近くの通常扉、または固定EVを操作。';return;}const b=BODIES.find(b=>b.doors.includes(near));this.experience.toggleDoor(b,near);}

 rescue(){this.experience.leave();this.experience.end();this.experience.blend=0;this.experience.focus=null;this.player={x:-1.2,y:LEVELS[1],z:4,yaw:Math.PI/2,pitch:0,owner:'F1'};this.passenger=null;if(this.liftActive){this.liftActive=false;this.liftY=this.liftTarget;}this.invalidate();this.message='デバッグ復帰：固定EV乗場へ移動。通常の物理的出口には含めません。';}
 referencePoint(name){const p=POINTS[name],q=this.positions[p.body];return{x:q.x+p.x,y:q.y,z:q.z+p.z};}
}
